export function headshotFocus(url: string | undefined, isLg: boolean): string | undefined {
  if (!url) return undefined;
  const slug = url.split("/").pop()?.replace(/\.webp$/, "") ?? "";
  const entry = HEADSHOT_FOCUS[slug];
  if (!entry) return undefined;
  return isLg ? entry.lg : entry.sq;
}
